import{z as l,x as p,o as e,c as A,q as i,j as o,D as E,d as n,s as r,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"欧氏空间与开集","description":"","frontmatter":{"title":"欧氏空间与开集","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/euclidean-open-set.md","filePath":"econ/euclidean-open-set.md","lastUpdated":1791413859000}'),d={name:"econ/euclidean-open-set.md"};function c(m,a,h,_,b,D){const B=p("Mermaid");return e(),A("div",null,[a[2]||(a[2]=i('<h1 id="欧氏空间与开集" tabindex="-1">欧氏空间与开集 <a class="header-anchor" href="#欧氏空间与开集" aria-label="Permalink to &quot;欧氏空间与开集&quot;">​</a></h1><div class="epigraph"><p>消费束、价格、资本存量都先是 $\\mathbb{R}^n$ 里的点；「附近」必须先写成开球，连续与紧才能开口。</p><footer>—— 据 Rudin, Principles of Mathematical Analysis, 第 2 章；Ok, Real Analysis with Economic Applications, 2007 整理</footer></div><p>本课是金融栏第一课，也是「数学与优化基础」的第一课。后面的凸集、分离、KKT、不动点、贝尔曼与条件期望，以及微观主干的连续偏好与闭预算，都默认已经会在 \\(\\mathbb{R}^n\\) 里说开集、闭集、收敛与紧。后课默认已经读完本课。不要从偏好或效用起笔：排序还没出场，舞台是空间。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一个消费计划是 \\(n\\) 个非负数，一个价格是 \\(n\\) 个正数，一个宏观状态可以是资本与生产率的一对。它们都是向量。若只把向量当成「一列数字」，「价格微调时需求怎么变」「最优是否存在」没有共同语言：前者要连续映射，后者要闭集上的极值。两者都依赖<strong>开集</strong>。</p><p>\\(U\\subset\\mathbb{R}^n\\) 为开集，若每个 \\(x\\in U\\) 都有 \\(\\varepsilon\\gt 0\\) 使开球 \\(B_\\varepsilon(x)=\\{y:\\|y-x\\|\\lt \\varepsilon\\}\\) 仍在 \\(U\\) 内。闭集是开集的补。内部、边界、闭包由开集生成：\\(\\operatorname{int} A\\) 是含于 \\(A\\) 的最大开集，\\(\\bar A\\) 是含 \\(A\\) 的最小闭集，\\(\\partial A=\\bar A\\setminus\\operatorname{int} A\\)。序列 \\(x_k\\to x\\) 当且仅当每个含 \\(x\\) 的开集最终吞掉整个尾段。</p><p><span class="marginnote">开集的日常译法是「每个成员都带一小圈缓冲地带」：不管站在集合里哪个点，往任何方向挪一小步都还在集合里。一寸缓冲都没有的点就是边界点——开集把这些点留在外面，闭集把它们包在里面。开与闭说的都是「边界归属」，不是「能不能进入」。</span></p><h3 id="开不是「可以买到」" tabindex="-1">开不是「可以买到」 <a class="header-anchor" href="#开不是「可以买到」" aria-label="Permalink to &quot;开不是「可以买到」&quot;">​</a></h3><p>数学开集只谈邻域。预算 \\(\\{x:p\\cdot x\\le w\\}\\) 作为制度约束可以很「开」——你能买附近的束——但它是闭半空间：边界上的花光预算点属于集合。不要把开集读成可达，也不要把闭集读成禁止。后课<a href="/econ/marshallian-demand">预算集与马歇尔需求</a>会用闭性保证极限仍可行；本课只把词汇钉死。</p><p><span class="marginnote">本课只取 \\(\\mathbb{R}^n\\) 的欧氏拓扑。无穷维商品空间、弱* 拓扑不在主干。换拓扑时邻域会变，「开集决定收敛」这条骨架不变。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>欧氏范数 \\(\\|x\\|=(\\sum_i x_i^2)^{1/2}\\) 给出度量 \\(d(x,y)=\\|x-y\\|\\)。所有范数在有限维等价：开集族相同，连续性不依赖于你用 \\(\\ell_2\\) 还是 \\(\\ell_\\infty\\)。这是后课敢直接写 \\(x_k\\to x\\) 而不声明范数的原因。</p><p><span class="marginnote">「距离」就是直尺量法：\\(d((1,2),(3,5))=\\sqrt{(3-1)^2+(5-2)^2}=\\sqrt{13}\\approx 3.61\\)。开球 \\(B_\\varepsilon(x)\\) 即「到 \\(x\\) 距离严格小于 \\(\\varepsilon\\) 的所有点」，在平面上是不含圆周的圆盘——「小于」而不是「小于等于」，正是开与闭的分水岭。</span></p><p>紧集：每个开覆盖有有限子覆盖。在 \\(\\mathbb{R}^n\\) 里，Heine–Borel 说紧 \\(\\Leftrightarrow\\) 闭且有界。Weierstrass：连续实函数在非空紧集上达到最大与最小。价格 \\(p\\gg 0\\) 时，预算与 \\(\\mathbb{R}_+^n\\) 的交可以紧化——有界来自 \\(x_i\\le w/p_i\\)，闭来自闭半空间与闭象限的交。没有紧，后课「最优非空」缺舞台。</p><p>连续映射 \\(f:X\\to Y\\)：开集的原像是开集；等价于保序列极限。后课把偏好的上优集写成闭集，就是在用这套语言，不在本课引入 \\(\\succsim\\)。</p>',15)),(e(),o(s,null,{default:E(()=>[r(B,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%AC%A7%E6%B0%8F%E7%A9%BA%E9%97%B4%20R%5En%22%5D%20--%3E%20O%5B%22%E5%BC%80%E7%90%83%E4%B8%8E%E5%BC%80%E9%9B%86%22%5D%0A%20%20O%20--%3E%20C%5B%22%E9%97%AD%E9%9B%86%E3%80%81%E9%97%AD%E5%8C%85%E3%80%81%E8%BE%B9%E7%95%8C%22%5D%0A%20%20C%20--%3E%20K%5B%22%E7%B4%A7%EF%BC%9A%E9%97%AD%E4%B8%94%E6%9C%89%E7%95%8C%22%5D%0A%20%20K%20--%3E%20W%5B%22%E8%BF%9E%E7%BB%AD%E5%87%BD%E6%95%B0%E8%BE%BE%E5%88%B0%E6%9E%81%E5%80%BC%22%5D%0A%20%20W%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%87%B8%E9%9B%86%E4%B8%8E%E5%8F%AF%E8%A1%8C%E5%9F%9F%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[n("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"非负象限 \\(\\mathbb{R}_+^n\\) 是闭集：非负序列的极限仍非负。开正象限 \\(\\mathbb{R}_{++}^n\\) 是开集，内部点可以沿坐标微移仍保持严格为正。后课若写 \\(p\\gg 0\\)，是在开正象限里说话，才能用 \\(w/p_i\\) 给出预算的界。",-1)),(e(),o(s,null,{default:E(()=>[r(B,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22R%2B%2B%20%E9%87%8C%E7%9A%84%E7%82%B9%3A%20%E6%AF%8F%E4%B8%AA%20x_i%20%E9%83%BD%E4%B8%A5%E6%A0%BC%E5%A4%A7%E4%BA%8E%200%22%5D%20--%3E%20B%5B%22%E6%B2%BF%E4%BB%BB%E4%BD%95%E6%96%B9%E5%90%91%E5%BE%AE%E7%A7%BB%E4%B8%80%E5%B0%8F%E6%AD%A5%2C%20%E4%BB%8D%E4%B8%A5%E6%A0%BC%E4%B8%BA%E6%AD%A3%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%AF%8F%E4%B8%AA%E7%82%B9%E9%83%BD%E6%9C%89%E5%BC%80%E7%90%83%E8%A3%85%E5%9C%A8%E9%9B%86%E5%90%88%E5%86%85%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%89%80%E4%BB%A5%20R%2B%2B%20%E6%98%AF%E5%BC%80%E9%9B%86%22%5D%0A%20%20E%5B%22R%2B%20%E9%87%8C%E7%9A%84%E7%82%B9%3A%20%E5%85%81%E8%AE%B8%E6%9F%90%E4%B8%AA%20x_i%20%3D%200%22%5D%20--%3E%20F%5B%22%E8%BE%B9%E7%95%8C%E7%82%B9%E5%91%A8%E5%9B%B4%E4%B8%80%E6%AD%A5%E5%B0%B1%E5%8F%AF%E8%83%BD%E8%B7%8C%E8%BF%9B%E8%B4%9F%E6%95%B0%22%5D%0A%20%20F%20--%3E%20G%5B%22%E4%BD%86%E9%9D%9E%E8%B4%9F%E5%BA%8F%E5%88%97%E7%9A%84%E6%9E%81%E9%99%90%E4%BB%8D%E9%9D%9E%E8%B4%9F%2C%20%E4%B8%8D%E9%80%83%E5%87%BA%E9%9B%86%E5%90%88%22%5D%0A%20%20G%20--%3E%20H%5B%22%E6%89%80%E4%BB%A5%20R%2B%20%E6%98%AF%E9%97%AD%E9%9B%86%2C%20%E8%BE%B9%E7%95%8C%E5%B1%9E%E4%BA%8E%E5%AE%83%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p>收敛把「附近」操作化。需求对价格连续，意思是 \\(p_k\\to p\\) 时 \\(x(p_k)\\to x(p)\\)。对应（集值）的上半连续要把开集换成「不含极限点的开集最终也不含尾段」，那是<a href="/econ/uhc-correspondence">上半连续对应</a>的缺口；本课只准备单值连续。</p><p><span class="marginnote">边界点是麻烦的几何位置：每个邻域既碰集合内又碰集合外。角点解、互补松弛，后课都会落在边界上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲一般拓扑空间，不证 Tychonoff，不把度量空间的完备性铺成教材。完备会在<a href="/econ/contraction-mapping">压缩映射</a>里以 Banach 空间的形式回来，那时默认 \\(\\mathbb{R}^n\\) 已经完备。排序、效用、需求都还没有对象。下一课只问：哪些子集允许「平均仍在里面」。</p><p><span class="marginnote">这一步如果省了，后面会连环塌：没有开集就说不清「收敛到哪」，没有闭就接不住极限，没有紧就保证不了「最优存在」。微观里「均衡存在」「解存在」这类定理，全部踩在开、闭、紧这三块砖上——所以第一课先修地基。</span></p><p>后课默认：对象住在 \\(\\mathbb{R}^n\\)；开、闭、内部、紧、序列收敛按本课使用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>金融栏从 \\(\\mathbb{R}^n\\) 的开集起笔；「附近」是开球，不是直觉。</li><li>闭集含极限；紧在有限维等于闭且有界，给 Weierstrass。</li><li>连续映射保极限；后课的连续偏好与连续需求都靠它。</li><li>开集不是制度可达，闭预算仍可购买边界点。</li><li>下一课：<a href="/econ/convex-set-combo">凸集与凸组合</a>。</li><li>出处：Rudin, <em>Principles of Mathematical Analysis</em>；Ok, <em>Real Analysis with Economic Applications</em>。</li></ul>',8))])}const C=l(d,[["render",c]]);export{x as __pageData,C as default};
